with alvo(sku, qtd) as (values ('STI002',1),('STI003',3),('CAP002',2),('BB007',2),('BB009',1),('DDP001',9),('ADC002',6),('ADC003',1),('ADC004',0),('ADC006',4),('ADC007',15),('ADC008',4),('ADC010',3),('ADC011',0),('ADC012',0),('ADC014',2),('ADC016',5),('N25002',0),('HGR001',3),('PPC005',2),('HGR010',4),('PAM004',4),('PPC006',4),('BB001',7),('BB002',9),('BB003',6),('BB005',5),('BB006',2),('BB016',8),('PAC007',2),('PAC008',2),('PAC024',2),('PAC019',3),('BB013',24),('BB014',27),('BB015',28),('PFM003',0),('PPC008',6),('ADC001',7),('ADC005',5),('ADC009',1),('ADC013',0),('ADC015',53),('ADC017',3),('N25001',1),('HGR004',3),('HGR005',2),('HGR006',5),('HGR007',5),('HGR008',7),('HGR009',5),('HGR011',2),('DDM264',38),('BB010',4),('BB011',3),('BB012',2),('OI2601',5),('OI2602',4),('OI2603',4),('OI2604',5),('OI2605',3),('OI2606',3),('WBR001',3),('WBR002',5),('WBR003',5),('CIT001',2),('CIT002',3),('D001',0),('HG001',0),('PAM001',0),('PPC001',0),('N24001',0),('HG002',0),('HG003',0),('HG004',0),('HG005',0),('BB004',0),('PPC002',0),('PPC003',0),('PPC004',0),('PPC102',0),('HG006',0),('HG007',0),('HG008',0),('HG009',0),('HG010',0),('PPC007',0),('HG011',0),('PAC001',0),('PAC002',0),('PAC003',0),('PAC004',0),('PAC005',0),('PAC006',0),('PAC009',0),('PAC010',0),('PAC011',0),('PAC012',0),('PAC013',0),('PAC014',0),('PAC015',0),('PAC016',6),('PAC017',0),('PAC018',0),('PAC020',0),('PAC021',0),('PAC022',0),('PAC023',0),('PAC025',0),('PAC026',0),('PAC027',0),('PAC028',0),('PAC029',0),('PAC030',1),('PAC031',10),('PAC032',3),('PFM001',0),('PFM002',0),('PFM004',10),('ADF001',0),('ADF002',0),('ADF003',0),('ADF004',0),('ADF005',0),('ADF006',0),('ADF007',0),('ADF008',0),('STI001',0),('CAP001',0),('CAP003',4),('ADC018',0),('ADC019',0),('PAM002',0),('PAM003',0),('DDM261',0),('DDM262',0),('DDM263',0),('HGR002',0),('HGR003',1),('HGR012',0),('HGR013',2),('BB008',0))
select ordem, conferencia, no_banco, esperado, case when no_banco = esperado then 'OK' else 'DIFERENTE' end as resultado from (
  select 1 as ordem, 'produtos' as conferencia, (select count(*) from public.produtos)::numeric as no_banco, 142::numeric as esperado
  union all select 2, 'vendas migradas', (select count(*) from public.vendas where origem = 'migracao'), 198
  union all select 3, 'itens de venda', (select count(*) from public.venda_itens), 252
  union all select 4, 'itens de venda ligados a produto (SKU)', (select count(*) from public.venda_itens where sku is not null), 222
  union all select 5, 'vendas do site já existentes no CRM (completadas)', (select count(*) from public.vendas where origem <> 'migracao' and pedido_externo is not null), 19
  union all select 6, 'movimentos de estoque', (select count(*) from public.movimentos_estoque), 328
  union all select 7, 'produtos com estoque diferente do esperado', (select count(*) from alvo a left join public.produtos p on p.sku = a.sku where p.estoque_atual is distinct from a.qtd), 0
  union all select 8, 'valor das vendas migradas (R$)', (select round(coalesce(sum(valor),0),2) from public.vendas where origem = 'migracao'), 10431.86
) x order by ordem;
